mapper.sql:
WHERE h.delete_yn = 'N'

  AND h.year = #{search.year}


  AND h.holiday_type = #{search.holidayType}


  AND h.use_yn = #{search.useYn}


  AND h.holiday_date >= #{search.dateFrom}


  AND h.holiday_date <= #{search.dateTo}


  AND h.holiday_name LIKE CONCAT('%', #{search.keyword}, '%')

mapper.select:

SELECT COUNT(1)
  FROM tb_holiday
 WHERE holiday_date = #{holidayDate}
   AND holiday_name = #{holidayName}
   AND delete_yn    = 'N'


  AND holiday_id <> #{excludeId}

mapper.delete:
DELETE FROM tb_holiday
 WHERE delete_yn = 'Y'
   AND updated_at <= #{cutoff}

mapper.select:
SELECT COUNT(*) FROM tb_holiday
 WHERE delete_yn = 'Y'
   AND updated_at <= #{cutoff}
